<#
.SYNOPSIS
    Deploys personal configuration files (dotfiles) to the Windows home directory.

.DESCRIPTION
    Install-WindowsUserConfiguration bootstraps a Windows development environment
    by deploying dotfiles using Tuckr. The script performs the following:
    - Removes broken symbolic links from the home directory
    - Creates PowerShell directory structure with WindowsPowerShell symlinked to PowerShell
    - Deploys dotfile packages using Tuckr (base packages: all, all-Windows)
    - Ensures .config/git/config includes config.all, config.os, config.local
    - Creates .config/git/config.local with user identity if it doesn't exist
    - Ensures .ssh/config includes config.d directory
    - Combines SSH authorized_keys from authorized_keys.d directory
    - Secures sensitive directories with proper ACLs via FixUp-Acls.ps1

    User identity (name and email) is resolved from git config, Windows user profile,
    or by prompting interactively. Identity is only written to config.local when the
    file is first created.

.PARAMETER Package
    Optional package names to deploy in addition to the base packages (all, all-Windows).
    Each package may have a Windows-specific variant (e.g., "work" and "work-Windows").

.EXAMPLE
    .\Install-WindowsUserConfiguration.ps1
    Deploys the base packages (all, all-Windows).

.EXAMPLE
    .\Install-WindowsUserConfiguration.ps1 -Package work, dev
    Deploys base packages plus the work and dev packages.

.PARAMETER Adopt
    If a file exists on the system and in the dotfiles repository, the version from the system
    will be used to overwrite the version in the dotfiles repository.

.PARAMETER Force
    If a file exists on the system and in the dotfiles repository, the version from the dotfiles
    repository will be used to overwrite the version on the system.

.EXAMPLE
    .\Install-WindowsUserConfiguration.ps1 -WhatIf
    Shows what would be done without making changes.

.EXAMPLE
    .\Install-WindowsUserConfiguration.ps1 -Force
    Deploys base packages, overwriting any existing files.

.NOTES
    Requires PowerShell 7.0 or later.
    Requires Windows.
    Requires tuckr to be installed (cargo install tuckr).

.LINK
    https://github.com/RaphGL/tuckr
#>

#Requires -Version 7.0

[CmdletBinding(SupportsShouldProcess)]
param(
    [Parameter(Position = 0)]
    [string[]]
    $Package,

    [switch]
    $Adopt,

    [switch]
    $Force
)

$ErrorActionPreference = 'Stop'
$InformationPreference = 'Continue'

if (-not $IsWindows) {
    throw "This script requires Windows."
}

###########
# Variables
###########

$script:ScriptRoot = $PSScriptRoot
$env:TUCKR_HOME = Join-Path $ScriptRoot 'Home'

###########
# Functions
###########

function Invoke-Run {
    param(
        [scriptblock]$ScriptBlock,
        [string]$Description
    )

    if ($WhatIfPreference) {
        Write-Information "Would run: $Description"
    }
    else {
        & $ScriptBlock
    }
}

function Add-SelectedGroups {
    # Adds symlinks for selected groups
    # Arguments: group names to add
    param(
        [string[]]$Groups
    )

    if ($Groups.Count -gt 0) {
        Write-Information "Deploying groups: $($Groups -join ', ')"

        $tuckrArgs = @()
        if ($WhatIfPreference) { $tuckrArgs += '--dry-run' }
        $tuckrArgs += 'add'
        if ($Adopt) { $tuckrArgs += '--adopt' }
        if ($Force) { $tuckrArgs += '--force' }
        $tuckrArgs += '--assume-yes'
        $tuckrArgs += '--only-files'
        $tuckrArgs += $Groups

        & tuckr @tuckrArgs
        if ($LASTEXITCODE -ne 0) {
            throw "tuckr failed with exit code $LASTEXITCODE"
        }
    }
}

function Ensure-TuckrVersion {
    # Ensure the required version of tuckr is installed
    # Currently requires git master due to issue #122: https://github.com/RaphGL/Tuckr/issues/122

    $cratesJson = Join-Path $HOME '.local' '.crates2.json'
    if ((Test-Path $cratesJson) -and (Select-String -Path $cratesJson -Pattern 'git\+https://github\.com/RaphGL/Tuckr' -Quiet)) {
        return
    }

    $installScript = Join-Path $ScriptRoot 'Home' 'Configs' 'all-Windows' 'local' 'bin' 'Install-Tuckr.ps1'

    if ($WhatIfPreference) {
        Write-Information "Would run: $installScript"
    }
    else {
        & $installScript
    }
}

function Get-SelectedGroups {
    # Returns groups to install based on selected packages
    # Must be called from Home/Configs directory
    param(
        [string[]]$Packages
    )

    $groups = @()

    # Add base packages
    if (Test-Path 'all') { $groups += 'all' }
    if (Test-Path 'all-Windows') { $groups += 'all-Windows' }

    # Add user-specified packages
    foreach ($pkg in $Packages) {
        if (Test-Path $pkg) { $groups += $pkg }
        if (Test-Path "$pkg-Windows") { $groups += "$pkg-Windows" }
    }

    return $groups
}

function Remove-BrokenLinks {
    Write-Information "Removing broken links from $HOME"

    if ($WhatIfPreference) {
        Write-Information "Would find and remove broken symlinks in $HOME"
        return
    }

    $excludePaths = @(
        (Join-Path $HOME 'AppData'),
        (Join-Path $HOME 'Application Data'),
        (Join-Path $HOME 'Cookies'),
        (Join-Path $HOME 'Local Settings'),
        (Join-Path $HOME 'NetHood'),
        (Join-Path $HOME 'PrintHood'),
        (Join-Path $HOME 'Recent'),
        (Join-Path $HOME 'SendTo'),
        (Join-Path $HOME 'Start Menu'),
        (Join-Path $HOME 'Templates'),
        (Join-Path $HOME 'node_modules')
    )

    Get-ChildItem -Path $HOME -Recurse -Force -ErrorAction SilentlyContinue |
        Where-Object {
            $item = $_
            # Check if it's a symlink
            ($item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -and
            # Check if not in excluded paths
            -not ($excludePaths | Where-Object { $item.FullName.StartsWith($_, [StringComparison]::OrdinalIgnoreCase) }) -and
            # Check if target doesn't exist (broken link)
            -not (Test-Path -LiteralPath $item.FullName -ErrorAction SilentlyContinue)
        } |
        ForEach-Object {
            Write-Information "Removing broken link: $($_.FullName)"
            Remove-Item -LiteralPath $_.FullName -Force
        }
}

function Remove-UnselectedGroups {
    # Removes symlinks for groups NOT in the selected set
    # Must be called from Home/Configs directory
    param(
        [string[]]$Groups
    )

    $allGroups = Get-ChildItem -Directory | Select-Object -ExpandProperty Name
    $toRemove = $allGroups | Where-Object { $_ -notin $Groups }

    if ($toRemove.Count -gt 0) {
        Write-Information "Removing unselected groups: $($toRemove -join ', ')"

        if ($WhatIfPreference) {
            Write-Information "Would run: tuckr rm $($toRemove -join ' ')"
        }
        else {
            & tuckr rm @toRemove
            if ($LASTEXITCODE -ne 0) {
                throw "tuckr rm failed with exit code $LASTEXITCODE"
            }
        }
    }
}

function Install-Dotfiles {
    Remove-BrokenLinks

    # Prepare home directory structure for Windows

    $documentsPath = [Environment]::GetFolderPath('MyDocuments')
    $powerShellPath = Join-Path $documentsPath 'PowerShell'
    $windowsPowerShellPath = Join-Path $documentsPath 'WindowsPowerShell'

    Invoke-Run -Description "Create $powerShellPath\Modules" -ScriptBlock {
        New-Item -ItemType Directory -Path (Join-Path $powerShellPath 'Modules') -Force | Out-Null
    }

    if (-not (Test-Path $windowsPowerShellPath)) {
        Invoke-Run -Description "Create symlink WindowsPowerShell -> PowerShell" -ScriptBlock {
            New-Item -ItemType SymbolicLink -Path $windowsPowerShellPath -Target $powerShellPath -Force | Out-Null
        }
    }
    elseif (-not ((Get-Item $windowsPowerShellPath).Attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
        # WindowsPowerShell exists but is not a symlink - remove and recreate
        Invoke-Run -Description "Replace WindowsPowerShell with symlink to PowerShell" -ScriptBlock {
            Remove-Item -Path $windowsPowerShellPath -Recurse -Force
            New-Item -ItemType SymbolicLink -Path $windowsPowerShellPath -Target $powerShellPath -Force | Out-Null
        }
    }

    # Install dotfiles using Tuckr

    $configsPath = Join-Path $env:TUCKR_HOME 'Configs'
    Push-Location $configsPath

    try {
        $groups = Get-SelectedGroups -Packages $Package
        Remove-UnselectedGroups -Groups $groups
        Add-SelectedGroups -Groups $groups
    }
    finally {
        Pop-Location
    }

    # Secure encrypted files

    Write-Information "Securing encrypted files" -InformationAction Continue
    $protectArgs = @()
    if ($WhatIfPreference) { $protectArgs += '--dry-run' }
    & git protect-encrypted-files @protectArgs

    # Resolve user identity

    $userName = $null
    $userEmail = $null

    # Try git config first
    try {
        $userName = & git config --global user.name 2>$null
    }
    catch { }

    if (-not $userName) {
        # Try Windows net user command
        try {
            $netUserOutput = & net user $env:USERNAME 2>$null
            $fullNameLine = $netUserOutput | Where-Object { $_ -match '^Full Name\s+' }
            if ($fullNameLine) {
                $userName = ($fullNameLine -replace '^Full Name\s+', '').Trim()
            }
        }
        catch { }
    }

    if (-not $userName) {
        $userName = Read-Host "Enter your full name"
    }

    # Try git config for email
    try {
        $userEmail = & git config --global user.email 2>$null
    }
    catch { }

    if (-not $userEmail) {
        $userEmail = Read-Host "Enter your email address"
    }

    # Ensure git config includes required files (XDG location)

    $gitConfigDir = Join-Path $HOME '.config' 'git'
    $gitConfigPath = Join-Path $gitConfigDir 'config'
    $gitConfigLocalPath = Join-Path $gitConfigDir 'config.local'

    Write-Information "Ensuring $gitConfigPath includes config.all, config.os, config.local"

    if ($WhatIfPreference) {
        if (-not (Test-Path $gitConfigPath)) {
            Write-Information "Would create $gitConfigPath with include directives"
        }
        else {
            foreach ($includePath in @('./config.all', './config.os', './config.local')) {
                if (-not (Select-String -Path $gitConfigPath -Pattern "path = $([regex]::Escape($includePath))$" -Quiet)) {
                    Write-Information "Would append include path $includePath to $gitConfigPath"
                }
            }
        }
    }
    else {
        New-Item -ItemType Directory -Path $gitConfigDir -Force | Out-Null

        if (-not (Test-Path $gitConfigPath)) {
            $gitConfig = @"
# Generated by Install-WindowsUserConfiguration
[include]
    path = ./config.all
    path = ./config.os
    path = ./config.local
"@
            Set-Content -Path $gitConfigPath -Value $gitConfig -Encoding UTF8
        }
        else {
            foreach ($includePath in @('./config.all', './config.os', './config.local')) {
                if (-not (Select-String -Path $gitConfigPath -Pattern "path = $([regex]::Escape($includePath))$" -Quiet)) {
                    & git config --file $gitConfigPath --add include.path $includePath
                }
            }
        }
    }

    # Create git config.local with user identity if it doesn't exist

    if (-not (Test-Path $gitConfigLocalPath)) {
        Write-Information "Creating $gitConfigLocalPath with user.name=$userName, user.email=$userEmail"

        if ($WhatIfPreference) {
            Write-Information "Would create $gitConfigLocalPath with user identity"
        }
        else {
            $gitConfigLocal = @"
# Generated by Install-WindowsUserConfiguration
[user]
    name = $userName
    email = $userEmail
"@
            Set-Content -Path $gitConfigLocalPath -Value $gitConfigLocal -Encoding UTF8

            # Add editor path to config.local (found via registry)
            $uninstallPaths = @(
                "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*",
                "HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*"
            )
            $vimKey = $uninstallPaths |
                ForEach-Object { Get-ItemProperty $_ -ErrorAction SilentlyContinue } |
                Where-Object { $_.DisplayName -like "*Vim*" } |
                Select-Object -First 1

            if ($vimKey.InstallLocation) {
                $vimPath = Join-Path $vimKey.InstallLocation "vim.exe"
                $vimPathEscaped = $vimPath -replace '\\', '/'
                & git config --file $gitConfigLocalPath core.editor "`"$vimPathEscaped`""
            }
            else {
                Write-Warning "Could not find Vim install location in registry; editor not configured"
            }
        }
    }

    # Ensure SSH config includes config.d directory

    $sshConfigDir = Join-Path $HOME '.ssh'
    $sshConfigPath = Join-Path $sshConfigDir 'config'

    Write-Information "Ensuring $sshConfigPath includes config.d/"

    if ($WhatIfPreference) {
        if (-not (Test-Path $sshConfigPath)) {
            Write-Information "Would create $sshConfigPath with Include directive"
        }
        elseif (-not (Select-String -Path $sshConfigPath -Pattern '^Include \./config\.d/\*$' -Quiet)) {
            Write-Information "Would append Include directive to $sshConfigPath"
        }
        else {
            Write-Information "$sshConfigPath already includes config.d/"
        }
    }
    else {
        New-Item -ItemType Directory -Path $sshConfigDir -Force | Out-Null

        if (-not (Test-Path $sshConfigPath)) {
            $sshConfig = @"
# Generated by Install-WindowsUserConfiguration
Include ./config.d/*
"@
            Set-Content -Path $sshConfigPath -Value $sshConfig -Encoding UTF8
        }
        elseif (-not (Select-String -Path $sshConfigPath -Pattern '^Include \./config\.d/\*$' -Quiet)) {
            Add-Content -Path $sshConfigPath -Value 'Include ./config.d/*' -Encoding UTF8
        }
    }

    # Combine authorized_keys

    $authorizedKeysDir = Join-Path $HOME '.ssh' 'authorized_keys.d'
    $authorizedKeysFile = Join-Path $HOME '.ssh' 'authorized_keys'

    if (Test-Path $authorizedKeysDir) {
        $keyFiles = Get-ChildItem -Path $authorizedKeysDir -File -ErrorAction SilentlyContinue

        if ($keyFiles.Count -gt 0) {
            Write-Information "Generating $authorizedKeysFile"

            if ($WhatIfPreference) {
                Write-Information "Would concatenate $($keyFiles.Count) files from $authorizedKeysDir"
            }
            else {
                $keyFiles | ForEach-Object { Get-Content $_.FullName } | Set-Content -Path $authorizedKeysFile -Encoding UTF8
            }
        }
    }

    # Fix ACLs on sensitive directories

    $fixUpAclsScript = Join-Path $ScriptRoot 'Configuration' 'Windows' 'Scripts' 'FixUp-Acls.ps1'
    if (Test-Path $fixUpAclsScript) {
        Write-Information "Fixing ACLs on sensitive directories"
        if ($WhatIfPreference) {
            Write-Information "Would run $fixUpAclsScript"
        }
        else {
            & $fixUpAclsScript
        }
    }

    # Configure tuckr environment (sets TUCKR_HOME user environment variable)

    $completeTuckrSetup = Join-Path $HOME 'local' 'bin' 'Complete-TuckrSetup.ps1'
    if (Test-Path $completeTuckrSetup) {
        if ($WhatIfPreference) {
            Write-Information "Would run: Complete-TuckrSetup.ps1 -TuckrHome $env:TUCKR_HOME"
        }
        else {
            & $completeTuckrSetup -TuckrHome $env:TUCKR_HOME
        }
    }

    Write-Information "Installation complete."
}

###########
# Main
###########

Ensure-TuckrVersion
Install-Dotfiles

# SPDX-License-Identifier: MIT
## Reference: 
# - https://learn.microsoft.com/en-us/dotnet/api/system.security.accesscontrol.filesystemaccessrule.-ctor?view=net-8.0#system-security-accesscontrol-filesystemaccessrule-ctor(system-string-system-security-accesscontrol-filesystemrights-system-security-accesscontrol-inheritanceflags-system-security-accesscontrol-propagationflags-system-security-accesscontrol-accesscontroltype)
# - https://stackoverflow.com/questions/17031552/how-do-you-take-file-ownership-with-powershell

#requires -Module Microsoft.PowerShell.Security
#requires -Version 7.0

using namespace System.IO
using namespace System.Security.AccessControl
using namespace System.Security.Principal

[CmdletBinding(PositionalBinding = $false)]
param()

Set-Variable -Option const disableInheritance $true
Set-Variable -Option const enableInheritance $false
Set-Variable -Option const keepInheritedPermissions $true
Set-Variable -Option const doNotKeepInheritedPermissions $false

Set-Variable -Option const AllChildrenInheritPermissionsFromDirectory ([InheritanceFlags]::ContainerInherit -bor [InheritanceFlags]::ObjectInherit)
Set-Variable -Option const OnlyApplyPermissionsToChildrenWithinDirectory ([PropagationFlags]::InheritOnly)

Push-Location ~

try {

    $windowsIdentity = [System.Security.Principal.WindowsIdentity]::GetCurrent()

    $accessRule = [System.Security.AccessControl.FileSystemAccessRule]::new(
        $windowsIdentity.Name,
        [System.Security.AccessControl.FileSystemRights]::FullControl,
        $AllChildrenInheritPermissionsFromDirectory,
        [System.Security.AccessControl.PropagationFlags]::None,
        [System.Security.AccessControl.AccessControlType]::Allow)

    foreach ($directory in
        (Get-Item '.Personal-secrets', '.gnupg', '.ssh') +
        (Get-ChildItem -Recurse -Force -Path Workspace\Personal -Attributes Directory | Where-Object { $_.Name -match '^(.Personal-secrets|.gnupg|.ssh)$' })) {

        try {
            $directoryAcl = Get-Acl $directory
            $directoryAcl.SetOwner($windowsIdentity.User)
            $directoryAcl.SetAccessRuleProtection($disableInheritance, $doNotKeepInheritedPermissions)

            for ($i = $directoryAcl.Access.Count; --$i -ge 0;) {
                [void]$directoryAcl.RemoveAccessRule($directoryAcl.Access[$i])
            }

            $directoryAcl.SetAccessRule($accessRule)
            [FileSystemAclExtensions]::SetAccessControl($directory, $directoryAcl)

            $directoryAcl = (Get-Acl $directory)

            [PSCustomObject]@{
                "File" = $directory
                "Mode" = $directory.Mode
                "Owner" = $directoryAcl.Owner
                "Access" = ConvertTo-Json $directoryAcl.Access -EnumsAsStrings -Compress
            }

            $childAcl = $directoryAcl
            $childAcl.SetAccessRuleProtection($enableInheritance, $doNotKeepInheritedPermissions)
            $childAcl.PurgeAccessRules([NTAccount]::new($windowsIdentity.Name))

            Get-ChildItem -Force -Recurse -Path $directory | ForEach-Object {
                $item = $_
                try {
                    Set-Acl -Path $_ -AclObject $childAcl
                    $acl = Get-Acl $_

                    [PSCustomObject]@{
                        "File" = $_
                        "Mode" = $_.Mode
                        "Owner" = $acl.Owner
                        "Access" = $acl.Access | ConvertTo-Json -EnumsAsStrings -Compress
                    }
                }
                catch {
                    Write-Error "[$item] $_"
                }
            }
                }
        catch {
            Write-Error "[$directory] $_"
        }
    }
}
finally {
    Pop-Location
}

#!/usr/bin/env pwsh
# SPDX-License-Identifier: MIT

#Requires -Version 7.2

[CmdletBinding(PositionalBinding = $false)]
param(
    [Parameter(Position = 1, Mandatory = $false)]
    [Version]
    $Version = ([Version]::new(3, 9, 9))
)

$ErrorActionPreference = 'Stop'

$uri = "https://dlcdn.apache.org/maven/maven-3/${Version}/binaries/apache-maven-${version}-bin.zip"
$downloads = Join-Path (Resolve-Path ~) Downloads 
$archive = Join-Path $downloads "apache-maven-${version}-bin.zip"
$sourceDir = Join-Path $downloads "apache-maven-${version}"
$targetDir = Join-Path $env:ProgramFiles apache maven, ${version}

Invoke-WebRequest $uri -OutFile $archive

if (Test-Path $sourceDir) {
    Remove-Item -Force -Recurse $sourceDir
}

Expand-Archive $archive -DestinationPath $downloads

if (Test-Path $targetDir) {
    Get-ChildItem $targetDir | Remove-Item -Force -Recurse
}
else {
    New-Item -ItemType Directory $targetDir | Out-Null
}

Move-Item (Join-Path $downloads "apache-maven-${version}" *) $targetDir

$machinePath = [Environment]::GetEnvironmentVariable('Path', [EnvironmentVariableTarget]::Machine)
[Environment]::SetEnvironmentVariable('Path', "%ProgramFiles%\apache\maven\${version}\bin;$machinePath", [EnvironmentVariableTarget]::Machine)

$env:Path = "$targetDir\bin\;$env:Path"
